using System;using System.IO;using System.Linq;using System.Text;using System.Reflection;using System.Collections.Generic;using UnityEditor;using UnityEngine;using MashBoxSDK.AnimationStudio;using Object=UnityEngine.Object;
public static class StudioBevelRepeatLiveValidation
{
 const BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;static int checks;static StringBuilder log=new StringBuilder();
 static string PathFor(string name)=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../bevel-repeat-live-"+name));
 static object Get(object o,string name)=>o.GetType().GetField(name,F).GetValue(o);
 static object Kind()=>Enum.Parse(typeof(StudioModelEditor).GetNestedType("LiveTool",F),"Bevel");
 static void Call(StudioModelEditor editor,string name)=>typeof(StudioModelEditor).GetMethod(name,F).Invoke(editor,new[]{Kind()});
 static void Check(bool valid,string message){if(!valid)throw new Exception(message);checks++;}
 static void Defaults(float width){ToolChannelPane.SetFloatDefault("Bevel Edges","Width",width);ToolChannelPane.SetFloatDefault("Bevel Edges","Subdivisions",0);ToolChannelPane.SetFloatDefault("Bevel Edges","Tension",1);ToolChannelPane.SetFloatDefault("Bevel Edges","Junction",0);}
 static void Select(StudioModelEditor editor,bool first){var top=new StudioMeshCuts(editor.Document.nodes[0]);var edges=(List<(int a,int b)>)typeof(StudioModelEditor).GetMethod("Edges",F).Invoke(editor,null);editor.Components.Clear();for(int i=0;i<edges.Count;i++){var a=top.Positions[edges[i].a];var b=top.Positions[edges[i].b];bool hit=first?a.z==-.5f&&b.z==-.5f&&((a.y==.5f&&b.y==.5f)||(a.x==.5f&&b.x==.5f)):Mathf.Abs(a.x-.5f)<1e-5&&Mathf.Abs(b.x-.5f)<1e-5&&Mathf.Abs(a.y-.5f)<1e-5&&Mathf.Abs(b.y-.5f)<1e-5;if(hit)editor.Components.Add(i);}Check(editor.Components.Count>0,"No selected edges");}
 static Color32[] Render(Mesh mesh,Material material,Camera camera,RenderTexture rt,string image=null){var old=RenderTexture.active;var oldCamera=Camera.current;RenderTexture.active=rt;GL.PushMatrix();var texture=new Texture2D(rt.width,rt.height,TextureFormat.RGBA32,false);try{GL.Clear(true,true,Color.black);GL.LoadProjectionMatrix(Matrix4x4.Ortho(-.85f,.85f,-.85f,.85f,.01f,10));GL.modelview=Matrix4x4.TRS(new Vector3(0,0,3),Quaternion.identity,Vector3.one).inverse;material.SetPass(0);for(int sub=0;sub<mesh.subMeshCount;sub++)Graphics.DrawMeshNow(mesh,Matrix4x4.Rotate(Quaternion.Euler(20,215,0)),sub);texture.ReadPixels(new Rect(0,0,rt.width,rt.height),0,0);texture.Apply();if(image!=null)File.WriteAllBytes(PathFor(image),texture.EncodeToPNG());var pixels=texture.GetPixels32();Check(pixels.Count(p=>p.r>40)>1000&&pixels.Count(p=>p.r<10)>1000,"Render must show geometry and background");return pixels;}finally{GL.PopMatrix();RenderTexture.active=old;Camera.SetupCurrent(oldCamera);Object.DestroyImmediate(texture);}}
 public static void Run(){EditorApplication.delayCall+=Validate;}
 static void Validate(){int exit=0;var doc=ScriptableObject.CreateInstance<StudioModelDocument>();var mesh=StudioModelDocument.BuildPrimitive(PrimitiveType.Cube,out var polys);doc.nodes.Add(new StudioModelDocument.Node{name="Repeated bevel",mesh=mesh,cutPolygons=polys,cutTriangles=mesh.triangles});var go=new GameObject("Bevel render camera");var camera=go.AddComponent<Camera>();camera.transform.position=new Vector3(1.8f,1.6f,-2.6f);camera.transform.LookAt(Vector3.zero);camera.orthographic=true;camera.orthographicSize=.85f;camera.aspect=1;camera.nearClipPlane=.01f;camera.farClipPlane=10;var rt=new RenderTexture(512,512,24);rt.Create();var material=new Material(Shader.Find("MashBox/Studio/Preview"));material.SetFloat("_CameraLighting",1);material.SetColor("_Color",Color.white);
 try{StudioBevelFlatTerminationValidation.Validate();StudioBevelProfileValidation.Validate();StudioBevelChainValidation.Validate();StudioPublicationValidation.Validate();using(var editor=new StudioModelEditor(()=>{})){editor.Load(doc);editor.SelectObject(0);editor.SetToolbarComponentMode(StudioModelEditor.ComponentMode.Edge);Defaults(.1f);Select(editor,true);Call(editor,"ApplyLiveTool");Check(new StudioMeshCuts(doc.nodes[0]).Faces.Count==8,"First L bevel topology differs");var filter=editor.Transforms[0].GetComponent<MeshFilter>();Render(filter.sharedMesh,material,camera,rt,"first.png");Select(editor,false);foreach(float width in new[]{.1f,.5f,.994f}){Defaults(width);Call(editor,"EvaluateLiveTool");var preview=(StudioMeshToolPreview)Get(editor,"livePreview");Check(preview!=null,"No repeat live preview");var work=preview.Targets[0].Work;var top=new StudioMeshCuts(work);Check(top.Faces.Count==9&&top.Positions.Distinct().Count()==14,"Repeat topology changed");var livePixels=Render(filter.sharedMesh,material,camera,rt,"second-"+width+".png");var expected=Render(work.mesh,material,camera,rt);Check(livePixels.SequenceEqual(expected),"Rendered live GPU mirror differs from CPU work at "+width);var cap=top.Faces.Last();Check(cap.Vertices.Count==5,"Flat terminal bevel must be one pentagon, not a strip plus cap");var a=top.Positions[cap.Vertices[0]];var n=Vector3.zero;for(int c=0;c<cap.Vertices.Count;c++)n+=Vector3.Cross(top.Positions[cap.Vertices[c]]-a,top.Positions[cap.Vertices[(c+1)%cap.Vertices.Count]]-a);n.Normalize();var normals=work.mesh.normals;float error=cap.Vertices.Max(v=>1-Vector3.Dot(normals[v].normalized,n));log.AppendLine("width="+width+" cap normal error="+error+" GPU mirror=match");Check(error<1e-4f,"Zero-subdivision cap uses curved normals: error="+error);}
 Call(editor,"ApplyLiveTool");var committed=mesh.vertices;editor.PerformWorkspaceHistory(false);Check(new StudioMeshCuts(doc.nodes[0]).Faces.Count==8,"Undo repeat bevel failed");editor.PerformWorkspaceHistory(true);Check(mesh.vertices.SequenceEqual(committed),"Redo repeat bevel failed");}}
 catch(Exception error){exit=1;log.AppendLine(error.ToString());}finally{File.WriteAllText(PathFor("result.txt"),(exit==0?"PASS "+checks+" repeat-bevel live/render/history assertions\n":"FAIL\n")+log);Object.DestroyImmediate(material);Object.DestroyImmediate(rt);Object.DestroyImmediate(go);Object.DestroyImmediate(mesh);Object.DestroyImmediate(doc);EditorApplication.delayCall+=()=>EditorApplication.Exit(exit);}}
}
